import { render } from '@testing-library/react';
import { Dispatch, SetStateAction } from 'react';

import Container from './Container';
import { NotificationOptions } from './interfaces';
import createNotificationManager from './manager';

describe('notifications', () => {
    it('renders safe HTML and forces links to open safely', () => {
        const notifications: NotificationOptions[] = [
            {
                id: 1,
                key: 1,
                type: 'error',
                text: '<b>Try</b> <a href="https://example.com" target="_self" onclick="alert(1)">again</a><script>alert(1)</script>',
                isClosing: false,
            },
            { id: 2, key: 2, type: 'info', text: '<a href="javascript:alert(1)">bad link</a>', isClosing: false },
            {
                id: 3,
                key: 3,
                type: 'info',
                text: <a href="https://react.example">React content</a>,
                isClosing: false,
            },
        ];
        const { container } = render(
            <Container notifications={notifications} removeNotification={() => {}} hideNotification={() => {}} />
        );

        expect(container.querySelector('b')?.textContent).toBe('Try');
        const links = container.querySelectorAll('a');
        expect(links).toHaveLength(3);
        links.forEach((link) => {
            expect(link.getAttribute('rel')).toBe('noopener noreferrer');
            expect(link.getAttribute('target')).toBe('_blank');
        });
        expect(links[0].getAttribute('href')).toBe('https://example.com');
        expect(links[0].hasAttribute('onclick')).toBe(false);
        expect(links[1].hasAttribute('href')).toBe(false);
        expect(container.querySelector('script')).toBeNull();
        expect(links[2].textContent).toBe('React content');
    });

    it('deduplicates non-success notifications by resolved key', () => {
        let notifications: NotificationOptions[] = [];
        const setNotifications: Dispatch<SetStateAction<NotificationOptions[]>> = (update) => {
            notifications = typeof update === 'function' ? update(notifications) : update;
        };
        const manager = createNotificationManager(setNotifications);

        manager.createNotification({ type: 'success', text: 'same', expiration: -1 });
        manager.createNotification({ type: 'error', text: 'same', expiration: -1 });
        manager.createNotification({ type: 'info', text: 'same', expiration: -1 });
        expect(notifications).toHaveLength(2);
        expect(notifications[0].type).toBe('success');
        expect(notifications[1].type).toBe('info');
        expect(notifications[1].key).toBe('same');

        manager.createNotification({ type: 'error', text: 'first', key: 'explicit', expiration: -1 });
        manager.createNotification({ type: 'warning', text: 'second', key: 'explicit', expiration: -1 });
        expect(notifications).toHaveLength(3);
        expect(notifications[2].text).toBe('second');
        expect(notifications[2].key).toBe('explicit');

        manager.createNotification({ type: 'error', text: <b>one</b>, expiration: -1 });
        manager.createNotification({ type: 'error', text: <b>one</b>, expiration: -1 });
        expect(notifications).toHaveLength(5);
        expect(notifications[3].key).toBe(notifications[3].id);
        expect(notifications[4].key).toBe(notifications[4].id);

        manager.createNotification({ type: 'success', text: 'same', expiration: -1 });
        expect(notifications).toHaveLength(6);
        expect(notifications[5].type).toBe('success');
    });
});
import { ReactNode } from 'react';

export type NotificationType = 'error' | 'warning' | 'info' | 'success';

export interface NotificationOptions {
    id: number;
    key: any;
    text: ReactNode;
    type: NotificationType;
    isClosing: boolean;
    disableAutoClose?: boolean;
}

export interface CreateNotificationOptions extends Omit<NotificationOptions, 'id' | 'type' | 'isClosing' | 'key'> {
    id?: number;
    key?: NotificationOptions['key'];
    type?: NotificationType;
    isClosing?: boolean;
    expiration?: number;
}
import { Dispatch, SetStateAction } from 'react';
import { NotificationOptions, CreateNotificationOptions } from './interfaces';

function createNotificationManager(setNotifications: Dispatch<SetStateAction<NotificationOptions[]>>) {
    let idx = 1;
    const intervalIds = new Map<number, any>();

    const removeInterval = (id: number) => {
        const intervalId = intervalIds.get(id);
        if (!intervalId) {
            return;
        }
        if (intervalId !== -1) {
            clearTimeout(intervalId);
        }
        intervalIds.delete(id);
    };

    const removeNotification = (id: number) => {
        const intervalId = intervalIds.get(id);
        if (!intervalId) {
            return;
        }
        removeInterval(id);
        return setNotifications((oldNotifications) => {
            return oldNotifications.filter(({ id: otherId }) => id !== otherId);
        });
    };

    const hideNotification = (id: number) => {
        // If the page is hidden, don't hide the notification with an animation because they get stacked.
        // This is to solve e.g. offline notifications appearing when the page is hidden, and when you focus
        // the tab again, they would be visible for the animation out even if they happened a while ago.
        if (document.hidden) {
            return removeNotification(id);
        }
        return setNotifications((oldNotifications) => {
            return oldNotifications.map((oldNotification) => {
                if (oldNotification.id !== id) {
                    return oldNotification;
                }
                return {
                    ...oldNotification,
                    isClosing: true,
                };
            });
        });
    };

    const createNotification = ({
        id = idx++,
        expiration = 3500,
        type = 'success',
        ...rest
    }: CreateNotificationOptions) => {
        if (intervalIds.has(id)) {
            throw new Error('notification already exists');
        }
        if (idx >= 1000) {
            idx = 0;
        }

        setNotifications((oldNotifications) => {
            const key = rest.key !== undefined ? rest.key : typeof rest.text === 'string' ? rest.text : id;
            const newNotification = {
                id,
                expiration,
                type,
                ...rest,
                key,
                isClosing: false,
            };
            if (type !== 'success') {
                const duplicateOldNotification = oldNotifications.find(
                    (oldNotification) => oldNotification.type !== 'success' && oldNotification.key === key
                );
                if (duplicateOldNotification) {
                    removeInterval(duplicateOldNotification.id);
                    return oldNotifications.map((oldNotification) => {
                        if (oldNotification === duplicateOldNotification) {
                            return {
                                ...newNotification,
                                key: duplicateOldNotification.key,
                            };
                        }
                        return oldNotification;
                    });
                }
            }
            return [...oldNotifications, newNotification];
        });

        intervalIds.set(id, expiration === -1 ? -1 : setTimeout(() => hideNotification(id), expiration));

        return id;
    };

    const clearNotifications = () => {
        intervalIds.forEach((intervalId) => {
            clearTimeout(intervalId);
        });

        intervalIds.clear();

        return setNotifications([]);
    };

    return {
        createNotification,
        removeNotification,
        hideNotification,
        clearNotifications,
    };
}

export type NotificationsManager = ReturnType<typeof createNotificationManager>;

export default createNotificationManager;
